function matchRule(prompt) {
  for (const rule of RULES) {
    const match = prompt.match(rule.match);
    if (match) {
      return { rule, captures: match.slice(1) };
    }
  }
  return { rule: RULES[RULES.length - 1], captures: [] };
}
