// src/server/mcp/server/endpoint.ts
function buildOpenFoxMcpServer(deps) {
  const server = new McpServer({
    name: "openfox",
    version: "1.0.0"
  });
  for (const tool of createOpenFoxMcpTools(deps)) {
    const config3 = { description: tool.description };
    if (Object.keys(tool.inputSchema).length > 0) {
      config3["inputSchema"] = tool.inputSchema;
    }
    server.registerTool(
      tool.name,
      config3,
      async (args) => tool.handler(args ?? {})
    );
  }
  return server;
}
function createOpenFoxMcpRouter(options) {
  const router = Router4();
  router.all("/", async (req, res) => {
    try {
      if (options.isAuthRequired() && !await options.isAuthorized(req)) {
        res.status(401).json({ error: "Unauthorized" });
        return;
      }
      const deps = options.resolveDeps();
      if (!deps) {
        res.status(503).json({ error: "MCP server is not ready" });
        return;
      }
      const server = buildOpenFoxMcpServer(deps);
      const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: void 0 });
      await server.connect(transport);
      await transport.handleRequest(req, res, req.body);
    } catch (error) {
      logger.error("MCP endpoint request failed", {
        error: error instanceof Error ? error.message : String(error)
      });
      if (!res.headersSent) {
        res.status(500).json({ error: "MCP request failed" });
      }
    }
  });
  return router;
}
function extractSessionToken(req) {
  const header = req.headers["x-session-token"];
  if (typeof header === "string" && header.length > 0) {
    return header;
  }
  const authorization = req.headers["authorization"];
  if (typeof authorization === "string" && authorization.startsWith("Bearer ")) {
    const token = authorization.slice("Bearer ".length).trim();
    return token.length > 0 ? token : null;
  }
  return null;
}

// src/server/routes/dev-server.ts
